	j := i
	for j < len(s) && s[j] >= '0' && s[j] <= '9' {
		j++
	}
	id, _ := strconv.ParseInt(s[i:j], 10, 64)
	return id
}

func truncate(s string) string {
	if len(s) > 200 {
		return s[:200] + "..."
	}
	return s
}

// Enter records a call and returns the deferred half, which records the return
// (or, when the frame is unwinding, a raise — then re-panics so behaviour is
// unchanged).
func Enter(symbol string, args ...KV) func(...any) {
	if enc == nil {
		return func(...any) {}
	}
	gid := goid()
	id := strconv.FormatInt(gid, 10) + "-" + strconv.FormatInt(counter.Add(1), 10)

	mu.Lock()
	st := stacks[gid]
	parent := ""
	if len(st) > 0 {
		parent = st[len(st)-1]
	}
	depth := len(st)
	stacks[gid] = append(st, id)
	mu.Unlock()

	m := map[string]string{}
	for _, kv := range args {
		m[kv.K] = truncate(fmt.Sprintf("%v", kv.V))
	}
	emit(event{Kind: "call", Symbol: symbol, InvocationID: id, ParentID: parent, Depth: depth, Args: m})

	return func(results ...any) {
		mu.Lock()
		if st := stacks[gid]; len(st) > 0 {
			stacks[gid] = st[:len(st)-1]
		}
		mu.Unlock()

		if r := recover(); r != nil {
			emit(event{Kind: "raise", Symbol: symbol, InvocationID: id, ParentID: parent, Depth: depth,
				Exception: truncate(fmt.Sprintf("%v", r))})
			panic(r) // observe, do not swallow
		}
		res := ""
		for i, r := range results {
			if i > 0 {
				res += ", "
			}
			res += fmt.Sprintf("%v", deref(r))
		}
		emit(event{Kind: "return", Symbol: symbol, InvocationID: id, ParentID: parent, Depth: depth, Result: truncate(res)})
	}
}

// deref unwraps the pointers-to-named-results the injector passes in, so the
// value recorded is the value the caller actually saw.
func deref(v any) any {
	rv := reflect.ValueOf(v)
	if rv.Kind() != reflect.Ptr {
		return v
	}
	if rv.IsNil() {
		return "<nil>"
	}
	e := rv.Elem().Interface()
	if err, ok := e.(error); ok {
		if err == nil {
			return "<nil>"
		}
		return err.Error()
	}
	return e
}
`

type Landscape struct {
	SessionID	string		`json:"session_id"`
	Wells		[]Well		`json:"wells"`
	Barriers	[]Barrier	`json:"barriers"`
	// Closed is false when a frame descended and never came back: a goroutine
	// leak, a swallowed context, an early exit. You see it as a shape.
	Closed		bool	`json:"closed"`
	OpenFrame	string	`json:"open_frame"`
	TestID		string	`json:"test_id"`
	Chain		string	`json:"chain"`
	// Escaped is the panic that left the instrumented set entirely — nothing in
	// the changed code caught it.
	Escaped	string		`json:"escaped,omitempty"`
	Chains	int		`json:"chains"`
	HotPath	[]string	`json:"hot_path"`
}

type ShimSpec struct {
	Language	string
	// Mode is how the shim attaches: "rewrite" (source instrumentation in a
	// scratch copy), "env" (preload/require hook), or "none".
	Mode	string
	Env	map[string]string
	Command	[]string
	Symbols	[]bundle.SymbolID
}
